      en: ["15th century", "Triangular plan", "Vivari Channel", "Republic of Venice"],
      es: ["Siglo XV", "Planta triangular", "Canal de Vivari", "República de Venecia"],
      pt: ["Século XV", "Planta triangular", "Canal Vivari", "República de Veneza"],
